head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15400";
scwin.dtree = undefined;
scwin.contn = null;
scwin.keyword = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isPop, sysInfoList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.contn = "${fn:replace(sysInfo.contn, \"\"\", \"\\\"\")}";
        scwin.keyword = "${fn:replace(param.keyword, \"\"\", \"\\\"\")}";
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15400.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_53", attr: "__html", fn: function () { return ([String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword")))].some(function (v) { return String(v === null ? '' : v).trim() !== ''; }) ? ("<span class=\"search\">'" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))) + "'</span> 검색결과") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_isPop", fn: function(){ return ((String(((dma_pageContext.get("isPop") ?? "")) === null ? '' : ((dma_pageContext.get("isPop") ?? ""))).length === 0)); } }, { id: "c_when_55", fn: function(){ return (!(String(((dma_pageContext.get("sysInfoList") ?? "")) === null ? '' : ((dma_pageContext.get("sysInfoList") ?? ""))).length === 0)); } }, { id: "tr_58", fn: function(){ return (!(String(((dma_pageContext.get("sysInfoList") ?? "")) === null ? '' : ((dma_pageContext.get("sysInfoList") ?? ""))).length === 0)); } }, { id: "tr_62", fn: function(){ return (!(String(((dma_pageContext.get("sysInfoList") ?? "")) === null ? '' : ((dma_pageContext.get("sysInfoList") ?? ""))).length === 0)); } }, { id: "tr_64", fn: function(){ return (!(String(((dma_pageContext.get("sysInfoList") ?? "")) === null ? '' : ((dma_pageContext.get("sysInfoList") ?? ""))).length === 0)); } }, { id: "tr_67", fn: function(){ return (!(String(((dma_pageContext.get("sysInfoList") ?? "")) === null ? '' : ((dma_pageContext.get("sysInfoList") ?? ""))).length === 0)); } }, { id: "c_otherwise_71", fn: function(){ return (!((!(String(((dma_pageContext.get("sysInfoList") ?? "")) === null ? '' : ((dma_pageContext.get("sysInfoList") ?? ""))).length === 0)))); } }, { id: "if_keyword", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_52", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_58", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_62", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_64", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_67", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_73", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) === null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(popsysinfo vs sysinfo) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_29_onclick
 * @description img_29 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_29_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15400.img_29_onclick' }); }
};

/**
 * @method
 * @name img_31_onclick
 * @description img_31 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_31_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil15400.img_31_onclick' }); }
};

/**
 * @method
 * @name btn_ViewSysInfo_onclick
 * @description btn_ViewSysInfo 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ViewSysInfo_onclick = async function(e){
    try {
        await scwin.viewSysInfo('' + dlt_sysInfoList.getCellData(0, "helpClssId") + '')
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil15400.btn_ViewSysInfo_onclick" });
    }
};

/**
 * @method
 * @name __ev_4_btn_ViewSysInfo_onclick
 * @description __ev_4_btn_ViewSysInfo 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_4_btn_ViewSysInfo_onclick = async function(e){
    try {
        await scwin.viewSysInfo('' + dlt_sysInfoList.getCellData(0, "helpClssId") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15400.__ev_4_btn_ViewSysInfo_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_69_onclick
 * @description krxpage_pagenavigator_69 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_69_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_69.page' }); } await scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/sysInfo.do",
        ref: "dma_SearchReq",
        target: "dlt_sysInfoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_ViewSysInfo_xhr
 * @description View Sys Info xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewSysInfo_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewSysInfo_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewSysInfo_xhr", unresolved: "action:self_submit:tx_fn_ViewSysInfo_xhr" };
};

/**
 * @method
 * @name viewSysInfo
 * @description view Sys Info 처리
 * @param {String} _sysInfoClssId _sysInfoClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewSysInfo = async function (_sysInfoClssId) {
    const frm = (document.viewForm || { elements: [] });
    frm.action = "/support/popSysInfo.do";
    $c.util.getComponent('dma_SearchReq').set('method', "viewSysInfoDetail");
    $c.util.getComponent('dma_SearchReq').set('sysInfoClssId', _sysInfoClssId);
    const result = await scwin.tx_fn_ViewSysInfo_xhr();
    const sysInfoContextDiv = $c.util.getComponent("sysInfoContext");
    sysInfoContextDiv.innerHTML = '';
    sysInfoContextDiv.innerHTML = result;
    scwin.dtree.open(_sysInfoClssId);
    scwin.dtree.selected(_sysInfoClssId);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', "searchSysInfo");
    frm.action = "/support/sysInfo.do";
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name replaceKeyword
 * @description replace Keyword 처리
 * @param {String} _srcStr _srcStr
 * @param {*} _keyword _keyword
 * @returns {void}
 * @hidden N
 */
scwin.replaceKeyword = function (_srcStr, _keyword) {
    document.write(_srcStr.replace(new RegExp(_keyword, "g"), "<span class='search'>" + _keyword + "</span>"));
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initValue = async function () {
    for (let i = 0; i < scwin.dtree.aNodes.length; i++) {
        if (!scwin.dtree.aNodes[i]._hc) {
            await scwin.viewSysInfo(scwin.dtree.aNodes[i].id);
            break;
        }
    }
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};
